-- Migration: old nado (`nadoma_base`.`annonces`) -> new nado (`annonces`)
--
-- The new `annonces` schema is a superset of the old one, so every column
-- referenced below exists in the new table. New-only columns (pack_id,
-- matricule, images, verified, featured_position, show_in_homepage,
-- homepage_position, is_homepage, esp, antipatinage, ... safety/comfort
-- flags) will take their DEFAULTs (NULL or 0).
--
-- How to run:
--   1. In phpMyAdmin, select the NEW database (e.g. `autoench_base`).
--   2. Make sure the `annonces` table already exists (import the new dump first).
--   3. Import this file, OR run from the command line:
--        mysql -u root autoench_base < migrate_annonces_old_to_new.sql
--
-- Re-running is safe: INSERT IGNORE skips rows whose `id` already exists.
-- To force overwrite of existing rows, replace INSERT IGNORE with REPLACE
-- (change the two occurrences below).

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
START TRANSACTION;





COMMIT;
